-- --- CHECKS (run after COMMIT, alone, in a fresh session; one row) ---------------------------------
SELECT
  (SELECT count(*) FROM backup_20261012_facts_031)                                                                              AS backup_facts,
  (SELECT count(*) FROM player_facts WHERE owner_method LIKE 'unowned by 031:%' AND player_id IS NULL)     AS coyotes_unowned,
  (SELECT count(*) FROM player_facts WHERE owner_method = '1972-96 Winnipeg Jets, NHL consolidation 24 Sep 2026 (031)')                                         AS jets_added,
  (SELECT string_agg(f.fact_value, ', ' ORDER BY f.fact_value) FROM player_facts f JOIN players p ON p.id = f.player_id WHERE p.wikipedia_page_id = 469924 AND f.sport = 'NHL' AND f.fact_value IN ('Jets', 'Coyotes')) AS hawerchuk,
  (SELECT string_agg(f.fact_value, ', ' ORDER BY f.fact_value) FROM player_facts f JOIN players p ON p.id = f.player_id WHERE p.wikipedia_page_id = 264865 AND f.sport = 'NHL' AND f.fact_value IN ('Jets', 'Coyotes')) AS selanne,
  (SELECT string_agg(f.fact_value, ', ' ORDER BY f.fact_value) FROM player_facts f JOIN players p ON p.id = f.player_id WHERE p.wikipedia_page_id = 440389 AND f.sport = 'NHL' AND f.fact_value IN ('Jets', 'Coyotes')) AS doan,
  (SELECT round(sum(t.tenure)::numeric, 3) FROM prior_tenure t JOIN players p ON p.id = t.player_id WHERE p.wikipedia_page_id = 469924 AND t.team = 'Jets') AS hawerchuk_jets_tenure,
  (SELECT count(*) FROM prior_tenure t JOIN players p ON p.id = t.player_id WHERE p.wikipedia_page_id = 469924 AND t.team = 'Coyotes') AS hawerchuk_coyotes_tenure_rows,
  (SELECT bool_and(relrowsecurity) FROM pg_class WHERE relname IN ('backup_20261012_facts_031', 'backup_20261012_tenure_031'))                         AS backup_rls,
  (SELECT count(*) FROM information_schema.role_table_grants WHERE table_name IN ('backup_20261012_facts_031', 'backup_20261012_tenure_031') AND grantee IN ('anon', 'authenticated')) AS backup_browser_grants;
